        // Create a deque to simulate the pile
        Deque<String> pile = new ArrayDeque<>();
        for (String card : cards) {
            pile.addLast(card);
        }

        // Dealer starts with two cards
        if (pile.size() < 2) {
            // Not enough cards, but problem guarantees valid input
            return;
        }

        List<String> hand = new ArrayList<>();
        hand.add(pile.pollFirst());
        hand.add(pile.pollFirst());

        // Calculate initial score
        int score = calculateScore(hand);

        // Dealer draws while score < 17
        while (score < 17 && !pile.isEmpty()) {
            String drawnCard = pile.pollFirst();
            hand.add(drawnCard);
            score = calculateScore(hand);
        }

        System.out.println(score);
    }

    // Calculate the best blackjack score (closest to 21 without busting)
    private static int calculateScore(List<String> hand) {
        int total = 0;
        int aces = 0;

        for (String card : hand) {
            int value = getCardValue(card);
            if (value == 11) {
                aces++;
            }
            total += value;
        }

        // Adjust aces from 11 to 1 if needed to avoid busting
        while (total > 21 && aces > 0) {
            total -= 10;
            aces--;
        }

        return total;
    }

    // Get the numeric value of a card (2-10, J/Q/K = 10, A = 11 initially)
    private static int getCardValue(String card) {
        // Card representation: first character is value, second is suit (or two chars for 10)
        String value;
        if (card.length() == 3) {
            value = card.substring(0, 2); // "10"
        } else {
            value = card.substring(0, 1);
        }

        switch (value) {
            case "A": return 11;
            case "K":
            case "Q":
            case "J": return 10;
            default: return Integer.parseInt(value);
        }
    }
}

